import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.wVcpyw2-.js";const p=JSON.parse('{"title":"AI 生成页面","description":"AI 生成页面：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/ai-panel.md","filePath":"features/ui-editor/ai-panel.md","lastUpdated":1785020677000}'),i={name:"features/ui-editor/ai-panel.md"};function n(s,a,l,d,h,u){return e(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="ai-生成页面" tabindex="-1">AI 生成页面 <a class="header-anchor" href="#ai-生成页面" aria-label="Permalink to &quot;AI 生成页面&quot;">​</a></h1><p>UI 编辑器内置 <strong>AI 助手</strong>，可根据文字描述自动生成页面布局，再人工微调后保存。</p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><p>在可视化编辑器（<strong>设计</strong> 界面）中：</p><ul><li><strong>宽屏</strong>：右侧或独立栏 <strong>AI</strong> 面板</li><li><strong>手机管理端</strong>：底部 Tab 切换到 <strong>AI</strong></li></ul><h2 id="使用步骤" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h2><h3 id="_1-描述需求" tabindex="-1">1. 描述需求 <a class="header-anchor" href="#_1-描述需求" aria-label="Permalink to &quot;1. 描述需求&quot;">​</a></h3><p>在输入框用自然语言说明想要的页面，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>做一个校园首页：顶部轮播图，下面 4 列金刚区（二手、跑腿、投票、活动），</span></span>
<span class="line"><span>再下面放热门话题和笔记列表</span></span></code></pre></div><p>描述越具体，生成结果越接近预期（组件类型、顺序、数量）。</p><h3 id="_2-生成" tabindex="-1">2. 生成 <a class="header-anchor" href="#_2-生成" aria-label="Permalink to &quot;2. 生成&quot;">​</a></h3><p>点击 <strong>生成</strong>（或类似按钮），等待 AI 返回布局方案。</p><p>生成过程会调用服务端 AI 能力，需已配置 <a href="/features/ai">AI 中台</a>（供应商 → 模型 → 场景路由）。</p><h3 id="_3-预览与应用" tabindex="-1">3. 预览与应用 <a class="header-anchor" href="#_3-预览与应用" aria-label="Permalink to &quot;3. 预览与应用&quot;">​</a></h3><ul><li>生成结果以 <strong>预览</strong> 形式展示</li><li>确认后点击 <strong>应用到画布</strong></li><li><strong>会覆盖当前画布已有内容</strong>，重要页面请先 <strong>导出 JSON</strong> 备份</li></ul><h3 id="_4-人工微调" tabindex="-1">4. 人工微调 <a class="header-anchor" href="#_4-人工微调" aria-label="Permalink to &quot;4. 人工微调&quot;">​</a></h3><p>AI 生成后建议逐项检查：</p><ul><li>轮播图、金刚区图片是否需替换为实际上传素材</li><li><strong>点击动作</strong> 是否指向正确页面</li><li>列表类组件是否与 <strong>筛选标签</strong> 正确联动</li><li>间距、颜色在 <strong>样式</strong> Tab 中微调</li></ul><h3 id="_5-保存并启用" tabindex="-1">5. 保存并启用 <a class="header-anchor" href="#_5-保存并启用" aria-label="Permalink to &quot;5. 保存并启用&quot;">​</a></h3><p>与普通编辑相同：<strong>保存</strong> → 列表 <strong>启用</strong>。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不太适合</th></tr></thead><tbody><tr><td>快速搭首页框架</td><td>精细像素级视觉稿</td></tr><tr><td>新站点冷启动</td><td>复杂表单计价逻辑</td></tr><tr><td>复制相似结构到新区</td><td>圈子页头区专属配置</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>AI 使用的是 <strong>当前页面类型</strong> 允许的组件子集（例如服务表单页不会生成轮播图）</li><li>生成内容中的 <strong>示例图片、文案</strong> 需替换为真实运营素材</li><li>笔记列表等 <strong>数据组件</strong> 在编辑器中为演示数据，客户端会拉取真实 API</li><li>AI 调用计入 <a href="/features/ai">AI 用量</a>，可在 <strong>AI中台 → 用量与日志</strong> 查看</li></ul><h2 id="与-ai-中台的关系" tabindex="-1">与 AI 中台的关系 <a class="header-anchor" href="#与-ai-中台的关系" aria-label="Permalink to &quot;与 AI 中台的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>作用</th></tr></thead><tbody><tr><td><strong>AI 中台</strong></td><td>配置模型、密钥、场景路由（管理员一次性配置）</td></tr><tr><td><strong>UI 编辑器 AI 面板</strong></td><td>运营人员日常生成页面布局</td></tr></tbody></table><p>未配置 AI 中台时，AI 面板不可用或报错，请先在 <strong>AI中台 → 供应商管理</strong> 添加可用模型。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ai">AI 中台</a></li><li><a href="/features/ui-editor/interface">编辑器界面说明</a></li><li><a href="/features/ui-editor/components-basic">组件手册</a></li></ul>`,29)])])}const c=t(i,[["render",n]]);export{p as __pageData,c as default};
